// The second tier of Finger contracts. The planner draws a contract from a band three tiers wide and skips
// the last six played, so three contracts a tier left a member cycling through the same few. Each Finger now
// has six a tier. A contract is a scene written for it (who, where, why) plus the way that Finger's work ends:
// the outcome lines are shared by route and carry the scene's own place and counterpart.

import { rq } from './careerContracts.js';

const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const fill = (text, v) => text
  .replace(/\{Foe\}/g, cap(v.foe)).replace(/\{foe\}/g, v.foe)
  .replace(/\{Place\}/g, cap(v.place)).replace(/\{place\}/g, v.place);

